#!/usr/bin/env node
// arthome-collect-agent-docs — puts arthome-core's rules INTO this package so it
// can ship them.
//
// The documents live in `architecture/`, which is outside every package, so
// nothing published carries them. This copies the ones a consuming repository
// has to read into `packages/tooling/docs/`, which `files` ships and
// `.gitignore` ignores: it is BUILD OUTPUT, regenerated by `build`, so the copy
// inside this repository cannot drift from the original the way a committed one
// would.
//
// The copy in the CONSUMER is committed, and that is a different decision made
// for a different reason — see `sync-agent-docs.mjs`.

import fs from 'node:fs';
import path from 'node:path';
import process from 'node:process';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const PACKAGE_ROOT = path.resolve(HERE, '..');
const REPO_ROOT = path.resolve(PACKAGE_ROOT, '..', '..');

// WHAT A CONSUMING REPOSITORY MUST READ, and nothing else.
//
//   `critical-rules.md` is nineteen lines and is meant to be re-read every
//   session. `code-conventions.md` is how the code is written and why.
//
//   The rest of `architecture/` — the ADRs, the context map, the data model —
//   is deliberately NOT copied: it is reference, it is large, and a copy of it
//   in five repositories is the parallel table this project spent a week
//   removing. A consumer follows the link to arthome-core for those.
const WANTED = ['critical-rules.md', 'code-conventions.md'];

function main() {
  const out = path.join(PACKAGE_ROOT, 'docs');
  fs.mkdirSync(out, { recursive: true });
  let n = 0;
  for (const name of WANTED) {
    const from = path.join(REPO_ROOT, 'architecture', name);
    if (!fs.existsSync(from)) {
      console.error(`arthome-collect-agent-docs: architecture/${name} not found.`);
      return 1;
    }
    fs.copyFileSync(from, path.join(out, name));
    n += 1;
  }
  console.log(`arthome-collect-agent-docs: ${n} document(s) collected into packages/tooling/docs/`);
  return 0;
}

process.exit(main());
